BEGIN TRANSACTION;
CREATE TABLE categories (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT UNIQUE NOT NULL,
    description TEXT,
    icon_name TEXT,
    sort_order INTEGER DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE countries (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT UNIQUE NOT NULL,
    iso_code TEXT(2),
    region TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE guidance_types (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT UNIQUE NOT NULL,
    description TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE propulsion_types (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT UNIQUE NOT NULL,
    description TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE tile_cache_index (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    basemap_name TEXT NOT NULL,
    zoom_level INTEGER NOT NULL,
    tile_x INTEGER NOT NULL,
    tile_y INTEGER NOT NULL,
    file_path TEXT NOT NULL,
    file_size_bytes INTEGER,
    downloaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    last_accessed TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    access_count INTEGER DEFAULT 1,
    checksum_sha256 TEXT,
    UNIQUE(basemap_name, zoom_level, tile_x, tile_y)
);
CREATE TABLE weapon_images (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    weapon_id INTEGER NOT NULL REFERENCES weapons(id) ON DELETE CASCADE,
    image_path TEXT NOT NULL,
    is_primary BOOLEAN DEFAULT 0,
    caption TEXT,
    display_order INTEGER DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(weapon_id, image_path)
);
CREATE TABLE weapon_models (
	id INTEGER NOT NULL, 
	weapon_id INTEGER NOT NULL, 
	model_path TEXT NOT NULL, 
	model_format TEXT, 
	is_primary BOOLEAN, 
	caption TEXT, 
	display_order INTEGER, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (weapon_id, model_path), 
	FOREIGN KEY(weapon_id) REFERENCES weapons (id)
);
CREATE TABLE weapon_swot_reports (
	id INTEGER NOT NULL, 
	weapon_id INTEGER NOT NULL, 
	analyst TEXT, 
	scenario TEXT, 
	strengths TEXT, 
	weaknesses TEXT, 
	opportunities TEXT, 
	threats TEXT, 
	recommendations TEXT, 
	score_summary TEXT, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(weapon_id) REFERENCES weapons (id)
);
CREATE TABLE weapon_variants (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    parent_weapon_id INTEGER NOT NULL REFERENCES weapons(id) ON DELETE CASCADE,
    variant_name TEXT NOT NULL,
    range_km_override REAL,
    warhead_override TEXT,
    guidance_override TEXT,
    propulsion_override TEXT,
    notes TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(parent_weapon_id, variant_name)
);
CREATE TABLE weapons (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    
    -- Core Identification
    model TEXT NOT NULL,
    weapon_name TEXT NOT NULL,
    category_id INTEGER REFERENCES categories(id) ON DELETE SET NULL,
    country_id INTEGER REFERENCES countries(id) ON DELETE SET NULL,
    
    -- Physical Specifications (metric units)
    length_m REAL,
    diameter_m REAL,
    weight_kg REAL,
    
    -- Warhead Information
    warhead_type TEXT,
    warhead_weight_kg REAL,
    
    -- Performance Characteristics
    range_km REAL,
    speed_mach REAL,
    
    -- Technical Specifications
    guidance_id INTEGER REFERENCES guidance_types(id) ON DELETE SET NULL,
    propulsion_id INTEGER REFERENCES propulsion_types(id) ON DELETE SET NULL,
    platform TEXT,
    status TEXT CHECK(status IN ('operational', 'development', 'testing', 'retired', 'export-only')),
    
    -- Metadata & Administrative
    manufacturer TEXT,
    intro_year INTEGER,
    unit_cost_usd REAL,
    notes TEXT,
    
    -- Geospatial Coordinates (for map features)
    origin_lat REAL DEFAULT 31.5,
    origin_lon REAL DEFAULT 34.8,
    
    -- System Timestamps
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, is_favorite INTEGER NOT NULL DEFAULT 0,
    
    -- Constraints
    UNIQUE(model, country_id)
);
