    content=''weapons'', content_rowid=''id''
)');
This is the baseline model, the original AGM-158 cruise missile that entered service in the early 2000s.
Designed from the ground up to avoid detection and deliver devastating accuracy, the JASSM’s technical specs reflect its advanced engineering and battlefield versatility.
uses a 450 kg penetrator/blast-fragmentation warhead, capable of taking out fortified targets like bunkers and underground facilities.','F-15E, F-16, B-1B Lancer, B-52 Stratofortress, F-35');
CREATE TABLE 'weapons_fts_config'(k PRIMARY KEY, v) WITHOUT ROWID;
CREATE TABLE 'weapons_fts_data'(id INTEGER PRIMARY KEY, block BLOB);
CREATE TABLE 'weapons_fts_docsize'(id INTEGER PRIMARY KEY, sz BLOB);
CREATE TABLE 'weapons_fts_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID;
CREATE INDEX idx_weapons_category ON weapons(category_id);
CREATE INDEX idx_weapons_country ON weapons(country_id);
CREATE INDEX idx_weapons_range ON weapons(range_km);
CREATE INDEX idx_weapons_status ON weapons(status);
CREATE INDEX idx_weapons_search ON weapons(weapon_name, model, manufacturer);
CREATE INDEX idx_weapons_geo ON weapons(origin_lat, origin_lon);
CREATE INDEX idx_images_weapon ON weapon_images(weapon_id);
CREATE INDEX idx_variants_parent ON weapon_variants(parent_weapon_id);
CREATE INDEX idx_tiles_basemap ON tile_cache_index(basemap_name, zoom_level);
CREATE INDEX idx_tiles_access ON tile_cache_index(last_accessed);
CREATE INDEX idx_tiles_coords ON tile_cache_index(tile_x, tile_y, zoom_level);
CREATE TRIGGER weapons_ai AFTER INSERT ON weapons BEGIN
  VALUES (new.id, new.weapon_name, new.model, new.manufacturer, new.notes, new.platform);
END;
CREATE TRIGGER weapons_ad AFTER DELETE ON weapons BEGIN
  VALUES('delete', old.id, old.weapon_name, old.model, old.manufacturer, old.notes, old.platform);
END;
CREATE TRIGGER weapons_au AFTER UPDATE ON weapons BEGIN
  VALUES('delete', old.id, old.weapon_name, old.model, old.manufacturer, old.notes, old.platform);
  VALUES (new.id, new.weapon_name, new.model, new.manufacturer, new.notes, new.platform);
END;
CREATE INDEX ix_weapon_swot_reports_weapon_id ON weapon_swot_reports (weapon_id);
PRAGMA writable_schema=OFF;
DELETE FROM "sqlite_sequence";
COMMIT;
